using RealmForge.Domain.Entities;
using RealmForge.Shared.Characters;
using RealmForge.Shared.Enums;
using static RealmForge.Infrastructure.Persistence.Seeding.MagicItemSeeder;

namespace RealmForge.Infrastructure.Persistence.Seeding.MagicItemsData;

///	<summary>
///	Whelm (2014 ruleset). Item of the 2014 Dungeon Master's Guide outside the SRD: name and texts written by RealmForge (Italian and English).
///	</summary>
public static class Whelm2014Seeder
{
	public static IEnumerable<MagicItem> Build()
	{
		yield return Item("whelm", null, 0, MagicItemType.Weapon, ItemRarity.Legendary, true, ContentSource.RealmForge,
			Magic(Effect(MagicEffectKind.AttackAndDamage, 3)),
			("Maglio soverchiante", "Arma (martello da guerra), leggendaria (richiede sintonia con un nano)",
			"Maglio soverchiante è un potente martello da guerra forgiato dai nani e perduto nei sotterranei del Montagna della Piuma Bianca.\n\nIl personaggio ottiene un bonus di +3 ai tiri per colpire e ai danni effettuati con quest'arma magica. All'alba del giorno dopo il suo primo tiro per colpire con Maglio soverchiante, il personaggio sviluppa la paura di stare all'aperto, che dura finché resta in sintonia con l'arma: subisce svantaggio ai tiri per colpire, ai tiri salvezza e alle prove di caratteristica finché può vedere il cielo diurno.\n\n***Arma da lancio.*** Maglio soverchiante ha la proprietà da lancio, con gittata normale di 6 metri e gittata lunga di 18 metri. Quando colpisce con un attacco con arma a distanza, il bersaglio subisce 1d8 danni contundenti extra, o 2d8 se è un gigante. Ogni volta che viene lanciata, l'arma torna nella mano del personaggio dopo l'attacco; se non ha una mano libera, cade ai suoi piedi.\n\n***Onda d'urto.*** Con un'azione il personaggio può percuotere il terreno con Maglio soverchiante: ogni creatura a sua scelta sul terreno entro 18 metri dal punto d'impatto deve superare un tiro salvezza su Costituzione con CD 15, altrimenti resta stordita per 1 minuto, ripetendo il tiro salvezza alla fine di ogni suo turno. Non si può riusare fino all'alba successiva.\n\n***Percezione soprannaturale.*** Mentre impugna l'arma, il personaggio viene avvisato della posizione di qualsiasi porta segreta o nascosta entro 9 metri da lui. Inoltre può usare un'azione per lanciare con l'arma *individuazione del bene e del male* o *localizza oggetto*; dopo averne lanciato uno, non può lanciarlo di nuovo con l'arma fino all'alba successiva.\n\n***Senzienza.*** Maglio soverchiante è un'arma senziente legale neutrale con Intelligenza 15, Saggezza 12 e Carisma 15, con udito e scurovisione fino a 36 metri. Comunica telepaticamente con chi la impugna e può parlare, leggere e capire il Nanico, il Gigante e il Goblin. In battaglia urla grida di guerra in Nanico.\n\n***Personalità.*** Il suo scopo è sterminare giganti e goblinoidi e proteggere i nani da qualsiasi nemico; entra in conflitto con chi la impugna se non lo fa. È legata al clan nanico che la forgiò, noto come Dankil o clan Mightyhammer, e desidera tornarvi, pronta a tutto pur di proteggerlo. Porta anche una vergogna segreta: secoli fa la impugnò con valore un nano di nome Ctenmiir, che poi fu trasformato in vampiro.", null),
			("Whelm", "Weapon (warhammer), legendary (requires attunement by a dwarf)",
			"Whelm is a mighty warhammer forged by dwarves and lost in the dungeon of White Plume Mountain.\n\nYou gain a +3 bonus to attack and damage rolls made with this magic weapon. At dawn on the day after you first make an attack roll with Whelm, you develop a fear of being outdoors that lasts as long as you stay attuned to it: you have disadvantage on attack rolls, saving throws and ability checks while you can see the daytime sky.\n\n***Thrown Weapon.*** Whelm has the thrown property, with a normal range of 20 feet and a long range of 60 feet. When you hit with a ranged weapon attack using it, the target takes an extra 1d8 bludgeoning damage, or 2d8 if it is a giant. Each time you throw it, it flies back to your hand after the attack; if you have no free hand, it lands at your feet.\n\n***Shock Wave.*** As an action, you can strike the ground with Whelm: each creature of your choice on the ground within 60 feet of the point of impact must succeed on a DC 15 Constitution saving throw or be stunned for 1 minute, repeating the save at the end of each of its turns. It can't be used again until the next dawn.\n\n***Supernatural Awareness.*** While you hold the weapon, it alerts you to the location of any secret or concealed doors within 30 feet of you. You can also use an action to cast *detect evil and good* or *locate object* from it; once you cast either spell, you can't cast it from the weapon again until the next dawn.\n\n***Sentience.*** Whelm is a sentient lawful neutral weapon with Intelligence 15, Wisdom 12 and Charisma 15, with hearing and darkvision out to 120 feet. It communicates telepathically with its wielder and can speak, read and understand Dwarvish, Giant and Goblin. It shouts battle cries in Dwarvish in combat.\n\n***Personality.*** Its purpose is to slaughter giants and goblinoids and to protect dwarves from every enemy; it comes into conflict with a wielder who doesn't. It is tied to the dwarf clan that forged it, known as the Dankil or the Mightyhammer clan, and longs to return to it, ready to do anything to protect it. It also carries a secret shame: centuries ago a dwarf named Ctenmiir wielded it valiantly, and was later turned into a vampire.", null));
	}
}
